func (q *Queries) UpdateSkill(ctx context.Context, arg UpdateSkillParams) (Skill, error) {
	row := q.db.QueryRowContext(ctx, updateSkill,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.Category,
		arg.PromptTemplate,
	)
	var i Skill
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Category,
		&i.PromptTemplate,
		&i.CreatedAt,
	)
	return i, err
}
